"""Record bounded router/dispatch qualification. No native/provider calls."""
import json
from pathlib import Path
from movie_factory import production_knowledge as pk
from movie_factory import context_hygiene as ch
from movie_factory.production_workflow import Controller
from movie_factory.task_router import DATABASE

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'results/workflow332'


def save(name, value):
    (OUT / name).write_text(json.dumps(value, indent=2) + '\n')


def main():
    # Evidence generated by the existing bounded helper, not a guessed PASS.
    run = ROOT / '.runtime/context-hygiene/runs/workflow332-qualified-tests'
    receipt = json.loads((run / 'receipt.json').read_text())
    assert receipt['exit_code'] == 0, 'Tests not successful'
    stdout = ROOT / receipt['stdout']
    assert pk.file_hash(stdout) == receipt['stdout_sha256']
    (OUT / 'tests.txt').write_text(stdout.read_text())
    save('test-receipt.json', receipt)
    # Heuristic inventory, not a claim that textual matching discovers every
    # indirect shell launch. Shared runner paths are mechanically blocked.
    direct, shared = [], []
    for folder in ('src/movie_factory', 'scripts'):
        for p in sorted((ROOT / folder).rglob('*.py')):
            text = p.read_text()
            name = str(p.relative_to(ROOT))
            if 'run_blender(' in text: shared.append(name)
            if '--background' in text and ('subprocess' in text or 'Popen' in text): direct.append(name)
    save('entrypoint-inventory.json', {
        'method': 'Textual candidate scan only; indirect launches may be missed',
        'shared_runner_files': shared, 'direct_launch_candidate_files': direct,
        'mechanical': ['Controller.create invokes routing first', 'Shared Blender runner capability gate',
                       'Historical mf3d main refuses dispatch before side effects'],
        'procedural_only': 'Standalone legacy scripts and raw terminal calls quarantined in AGENTS; not OS intercepted',
        'registered_native_operations': ['inspect'], 'artistic_authoring_qualified': False})
    previous = pk.read_json(ROOT, 'results/sikh331/verification.json')['protected']
    protected = {p: {'expected': v['expected'], 'actual': pk.file_hash(ROOT / p)} for p, v in previous.items()}
    assert all(v['expected'] == v['actual'] for v in protected.values())
    assert pk.read_json(ROOT, 'results/sikh331/STATUS.json')['native_dispatch_closed'] is True
    save('protected.json', protected)
    ch.load(ROOT)  # Reviewed core pin, original rules and routes still consistent.
    task = pk.read_json(ROOT, 'results/workflow330/task.json')
    sources = ['results/workflow332/STRATEGY.md', 'results/workflow332/SOURCE_RECONCILIATION.md',
               'docs/knowledge/PLANNING_PIPELINE_330.md', 'docs/knowledge/EXPERT_LENS_PLANNING_328.md',
               'results/sikh331/PROOF_AUDIT.md']
    task.update(id='workflow332-router-admission',
        query='Mandatory router first native dispatch admission dependencies review no bypass',
        intent='Qualify local routing and admission control, not artistic execution',
        inputs={p: pk.file_hash(ROOT / p) for p in sources},
        execution_authority={'source': sources[0], 'scope': 'Director332 local implementation/tests'})
    save('task.json', task)
    packet = pk.task_packet(ROOT, task)
    assert packet['dispatch_ready'], packet['blockers']
    save('knowledge-packet.json', packet)
    applications = {
        'reuse_envelope': 'Extended existing controller, context, knowledge and Blender runner; only inspect registered, no artistic reuse qualification.',
        'authority': 'No Blender process, provider/model call, upload, installation, remote push or renewed331 allowance. Mocks exercise subprocess boundary.',
        'strategy': '332 strategy preceded construction; bounded routing/dependency proof before native integration. Remaining authoring gap explicitly retained.',
        'visual_gate': 'No media produced or passed.331 stays rejected. Static controls and process receipts are not artistic judgments.',
        'anticipation': 'Tested missing route, scope mismatch, prerequisite FAIL/NOT_RUN, stale evidence, interrupted reservation, substitution and job-name retries.',
        'stopping': 'Scoped software boundary complete; next is authoring-handler qualification, not presenting failed331 frames or resetting its corrections.',
        'versioning': 'Authority/route/engine/plan/source/output digests tested. Historical core prior bytes remain in Git; only inspected addition repinned.',
        'economics': 'No measured savings percentage, no token/cost inference. Operating capture excludes unknown bootstrap rather than fabricating completeness.',
        'retrieval': 'Fresh packet plus manual328/330/331/332 and AU13/16 reconciliation. Existing307 staleness preserved; no universal memory claim.',
        'current_state': 'Actual hashes of accepted film, rejected native and reference rechecked.331 remains closed;325 live allowance unchanged.',
        'au_reuse': 'Exact protected bytes preserved; tests/records local only, not a new remote backup. Native and semantic qualifications separated.',
        'au_review': 'Known-history finite controls only; semantic prose misclassification and wrong-method controls retained. No independent perceptual accuracy claim.'}
    evidence_paths = ['results/workflow332/tests.txt', 'results/workflow332/entrypoint-inventory.json',
                      'results/workflow332/protected.json', 'results/workflow332/SOURCE_RECONCILIATION.md',
                      'docs/knowledge/ROUTER_FIRST_332.md', 'src/movie_factory/task_router.py',
                      'src/movie_factory/native_admission.py', 'src/movie_factory/production_workflow.py',
                      'src/movie_factory/adapters/blender/runner.py', 'src/movie_factory/cli.py',
                      'tests/test_task_router332.py']
    evidence = [{'path': p, 'sha256': pk.file_hash(ROOT / p)} for p in evidence_paths]
    review = {'packet_digest': packet['packet_digest'], 'scope': 'Local software admission; mocks only',
        'checks': [{'id': o['id'], 'status': 'PASS', 'kind': o['check_kind'],
                    'action_taken': applications[o['id']],
                    'observation': 'Bounded evidence and limitations reviewed; no media or universal enforcement claim.',
                    'evidence': evidence} for o in packet['obligations']],
        'hypotheses': [{'prediction': 'The rule might remain an optional wrapper',
            'observation': 'Create routes first; shared runner and legacy CLI reject bypass. Raw shell remains outside code enforcement.',
            'response': 'Quarantine unsupported launchers and publish exact coverage boundary.', 'result': 'resolved'},
            {'prediction': 'Structured routing might be confused with prose understanding',
             'observation': 'Deliberately mislabeled render request routes show; cannot obtain native dispatch from that route.',
             'response': 'Retain semantic negative control and require explicit operation reconciliation.', 'result': 'resolved'}],
        'adjacent_regressions': 'Focused controller, serial runner, planning, knowledge/context/review, resources and331 closure tests. No full repository/native execution claim.',
        'stopping_reason': 'Scoped router and native-inspection admission implementation complete. Authoring handler and prospective artistic proof remain separate.'}
    save('knowledge-review.json', review)
    gate = pk.check_review(ROOT, packet, review); save('knowledge-gate.json', gate)
    assert gate['ready_for_review'], gate
    c = Controller(ROOT, DATABASE)
    save('routing-receipt.json', c.routing('workflow332-bootstrap'))
    report = {'tests': stdout.read_text().strip().splitlines()[-1], 'gate': gate,
              'native_processes': 0, 'external_calls': 0, 'production_approved': False,
              'native_authoring_qualified': False, 'universal_tool_interception': False,
              'semantic_routing_accuracy': None, 'measured_efficiency_gain': None,
              'protected_unchanged': True, 'evidence': evidence}
    save('report.json', report)
    print(json.dumps({k: report[k] for k in ('tests', 'gate', 'native_processes', 'native_authoring_qualified')}))


if __name__ == '__main__': main()
